const completionLimits=new Map();
function completionJson(value,status=200,origin=''){
 return new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Access-Control-Allow-Origin':origin,'Vary':'Origin','Access-Control-Allow-Methods':'GET, POST, OPTIONS','Access-Control-Allow-Headers':'Content-Type'}});
}
function normalizedVisitorIp(raw){
 if(typeof raw!=='string')return null;let ip=raw.trim().toLowerCase();
 if(/^\d+\.\d+\.\d+\.\d+$/.test(ip)){const parts=ip.split('.').map(Number);return parts.every(n=>n>=0&&n<=255)?parts.join('.'):null}
 if(!/^[0-9a-f:]+$/.test(ip)&&!/^::ffff:\d+\.\d+\.\d+\.\d+$/.test(ip))return null;
 try{ip=new URL('http://['+ip+']/').hostname.slice(1,-1);if(ip.startsWith('::ffff:')){const parts=ip.slice(7).split(':').map(p=>parseInt(p,16));if(parts.length===2)return [parts[0]>>8,parts[0]&255,parts[1]>>8,parts[1]&255].join('.')}return ip}catch{return null}
}
function validCompletion(body){
 const scenario=TRAINING_CASES[body?.segment],a=body?.attempt;if(!scenario||!a||a.status!=='done'||a.version!==scenario.version||a.index!==scenario.questions.length-1||!a.answers||typeof a.answers!=='object')return false;
 for(const q of scenario.questions){const answer=a.answers[q.id],selected=answer?.selected;if(!answer?.feedback||typeof answer.feedback.correct!=='boolean'||!Array.isArray(selected)||!selected.length||selected.length>q.options||new Set(selected).size!==selected.length||!selected.every(i=>Number.isInteger(i)&&i>=0&&i<q.options))return false;if(q.required&&!(selected.length===q.correct.length&&q.correct.every(i=>selected.includes(i))))return false}
 if(scenario.quiz?.length&&!scenario.quiz.every((correct,i)=>{const entry=a.quiz?.answers?.[i];return entry?.correct===true&&Array.isArray(entry.selected)&&entry.selected.length===correct.length&&correct.every(option=>entry.selected.includes(option))}))return false;
 return true;
}
async function trainingApi(request,env,url){
 const origin=request.headers.get('Origin')||'',allowed=origin===SITE_ORIGIN||origin===PAGES_ORIGIN||origin===LEGACY_PAGES_ORIGIN||origin===url.origin;
 if(origin&&!allowed||request.method==='POST'&&!allowed)return completionJson({message:'Источник запроса не разрешён.'},403,allowed?origin:'');
 const cors=origin||url.origin;
 if(request.method==='OPTIONS')return completionJson({},200,cors);
 if(url.pathname!=='/api/training/completions'||!['GET','POST'].includes(request.method))return completionJson({message:'Адрес или метод не поддерживается.'},405,cors);
 if(!env.DB)return completionJson({code:'STATS_NOT_READY',message:'Счётчик временно недоступен.'},503,cors);
 try{
  if(request.method==='GET'){
   const rows=await env.DB.prepare('SELECT segment, COUNT(*) AS total FROM training_completions GROUP BY segment').all();
   const counts={kksb:0,rgs:0,mmb:0};for(const row of rows.results||[])if(Object.hasOwn(counts,row.segment))counts[row.segment]=Number(row.total);
   return completionJson({counts},200,cors);
  }
  if(!request.headers.get('Content-Type')?.startsWith('application/json'))return completionJson({message:'Ожидается JSON.'},415,cors);
  if(!env.STATS_HASH_KEY)return completionJson({code:'STATS_NOT_READY',message:'Счётчик временно недоступен.'},503,cors);
  const ip=normalizedVisitorIp(request.headers.get('CF-Connecting-IP'));
  if(!ip)return completionJson({code:'VISITOR_IP_UNAVAILABLE',message:'Не удалось определить участника. Завершение будет отправлено позже.'},503,cors);
  const now=Date.now(),entry=completionLimits.get(ip);if(entry&&now-entry.start<60000){if(++entry.count>20)return completionJson({message:'Повторите запрос через минуту.'},429,cors)}else completionLimits.set(ip,{start:now,count:1});if(completionLimits.size>10000)completionLimits.clear();
  const raw=await request.text();if(raw.length>30000)return completionJson({message:'Слишком большой запрос.'},413,cors);
  let body;try{body=JSON.parse(raw)}catch{return completionJson({message:'Некорректный запрос.'},400,cors)}
  if(!validCompletion(body))return completionJson({message:'Для зачёта необходимо завершить все вопросы бизнес-кейса.'},400,cors);
  const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(env.STATS_HASH_KEY),{name:'HMAC',hash:'SHA-256'},false,['sign']);
  const digest=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(body.segment+'\n'+ip));
  const visitor=[...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('');
  const inserted=await env.DB.prepare('INSERT INTO training_completions (segment, visitor_hash, completed_at) VALUES (?, ?, ?) ON CONFLICT (segment, visitor_hash) DO NOTHING').bind(body.segment,visitor,new Date().toISOString()).run();
  const row=await env.DB.prepare('SELECT COUNT(*) AS total FROM training_completions WHERE segment = ?').bind(body.segment).first();
  return completionJson({segment:body.segment,total:Number(row.total),counted:Number(inserted.meta?.changes||0)>0},200,cors);
 }catch{console.error('training-stats-unavailable');return completionJson({message:'Счётчик временно недоступен. Завершение будет отправлено позже.'},503,cors)}
}

